  principale: [["PV",2815,2448,1860,1544,1228,930],["ATQ",184,160,135,112,89,68],["DÉF",184,160,135,112,89,68],["PV %","72 %","63 %","51 %","42 %","34 %","26 %"],["ATQ %","72 %","63 %","51 %","42 %","34 %","26 %"],["DÉF %","72 %","63 %","51 %","42 %","34 %","26 %"],["VIT",48,42,39,32,26,20],["Taux Crit %","67 %","58 %","47 %","39 %","31 %","24 %"],["Dég. Crit %","92 %","80 %","65 %","54 %","43 %","33 %"],["RÉS %","74 %","64 %","51 %","42 %","34 %","26 %"],["PRÉ %","74 %","64 %","51 %","42 %","34 %","26 %"]],
